<h1 class="h3 mb-4">Logi, audyt i bezpieczeństwo</h1>
<div class="accordion" id="logsAccordion"><?php foreach (['API' => $apiLogs, 'Pobrania' => $downloadLogs, 'Audyt' => $auditLogs, 'Zdarzenia bezpieczeństwa' => $securityEvents] as $title => $items): ?><div class="accordion-item"><h2 class="accordion-header"><button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#collapse<?= md5($title) ?>"><?= e($title) ?></button></h2><div id="collapse<?= md5($title) ?>" class="accordion-collapse collapse" data-bs-parent="#logsAccordion"><div class="accordion-body p-0"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><?php if (!empty($items[0])): foreach (array_keys($items[0]) as $column): ?><th><?= e((string) $column) ?></th><?php endforeach; endif; ?></tr></thead><tbody><?php foreach ($items as $row): ?><tr><?php foreach ($row as $value): ?><td><small><?= e(is_scalar($value) ? (string) $value : json_encode($value)) ?></small></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></div></div></div><?php endforeach; ?></div>
